"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[9612],{2108(e){e.exports=JSON.parse('{"title":"HTML \ud0dc\uadf8\uc758 \uc911\uc694\uc131.","date":"2024-01-11","coverUrl":null,"html":"<h2 data-notion-block-id=\\"e74f0567-e82d-4917-8153-89825a76d663\\" id=\\"e74f0567-e82d-4917-8153-89825a76d663\\">\uc554\uc2dc\uc801\uc778 \uc6f9</h2><a href=\\"https://www.htmhell.dev/adventcalendar/2023/21/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.htmhell.dev/adventcalendar/2023/21/</a><p data-notion-block-id=\\"9859426f-077a-4cef-8e6c-6331e6d68f91\\"><b>\uc2ec\uc724\uc12d</b>: \uc78a\uc744\ub9cc \ud558\uba74 \ucc3e\uc544\uc624\ub294 \uc6f9 \uc811\uadfc\uc131\uc5d0 \ub300\ud55c \uae00\uc785\ub2c8\ub2e4. HTML-AAM\uc73c\ub85c HTML \ud0dc\uadf8\ub4e4\uc740 \uc790\ub3d9\uc801\uc73c\ub85c \uc811\uadfc\uc131 API\ub85c  \ub9e4\ud551\ub418\uba70, \uc544\ubb34\ub9ac \uc77c\ubc18 div\ub098 span \uc694\uc18c\ub97c ARIA \uc18d\uc131\uacfc CSS \uc18d\uc131\uc73c\ub85c \ubcf4\uc870\ud55c\ub2e4\uace0 \ud574\ub3c4 \uc0c1\ud669\uc5d0 \ub9de\ub294 HTML \ud0dc\uadf8\ub97c \uc0ac\uc6a9\ud558\ub294 \uac83\uc774 \ub354 \uc88b\ub2e4\ub77c\ub294 \uac83\uc744 \uc608\uc2dc\uc640 \ud568\uaed8 \uc8fc\uc7a5\ud569\ub2c8\ub2e4. \ucd5c\uadfc <a href=\\"https://techblog.woowahan.com/15541/\\">\uc6b0\uc544\ud55c\ud615\uc81c\ub4e4</a>\uc5d0\uc11c\ub3c4 \uac04\ub2e8\ud55c \uc6f9 \uc811\uadfc\uc131\uc744 \uc18c\uac1c\ud558\uace0 \uc788\uc73c\ub2c8 \ub450 \uae00\uc744 \uc608\uc2dc\ub85c \uae30\uc5b5\ud558\uace0 \uc788\uc73c\uba74 \uc88b\uc2b5\ub2c8\ub2e4. </p><p data-notion-block-id=\\"e196a9c9-0344-4200-9b11-4f1e2ef1669f\\"><b>\ucd5c\uc6d0\ube48</b>: \ucd5c\uadfc \ubd84\uc0b0\ub418\ub294 \ucd08\uc810\uc744 \ub9de\ucd94\uae30 \uc704\ud574 div\uc5d0 <code>role=\\"button\\"</code> \ub4f1\uc744 \ub123\uc5b4\uc57c \ud558\ub294 \uacbd\uc6b0\uac00 \uc788\uc5c8\ub294\ub370, \uc5ed\uc2dc \uc815\ud655\ud55c \uc774\ud574\ub97c \ud558\uace0 \uc0ac\uc6a9\ud558\ub294 \uac83\uc774 \uc911\uc694\ud55c \uac83 \uac19\uc544\uc694. \uc9c4\uc785\uc7a5\ubcbd\uc774 \uc880 \ub192\ub2e4 \uc0dd\uac01\uc740 \ub4e4\uc9c0\ub9cc, \ubc18\ub4dc\uc2dc \ucc59\uaca8\uc57c \ud558\ub294 \ubd80\ubd84\uc774\uc8e0.</p><p data-notion-block-id=\\"561898f2-560d-4b21-92fc-a5dbac8e7051\\"><b>\uae40\ub300\uad00</b>: HTML \ud0dc\uadf8\ub4e4\uc740 \uc790\ub3d9\uc801\uc73c\ub85c \uc811\uadfc\uc131 API\ub85c \ub9e4\ud551\ud558\ub294\xa0<a href=\\"https://www.w3.org/TR/html-aam-1.0/\\">HTML-AAM</a>\uc774\ub77c\ub294 \uc0c8\ub85c\uc6b4 \uae30\uc220\uc744 \ubc30\uc6b0\uac8c \ub41c \uae00\uc774\uc5c8\uc2b5\ub2c8\ub2e4.\xa0\uc791\ub144 \ub9d0\uc5d0 \ubb38\uc11c\uac00 \ucd5c\uc2e0\ud654\ub41c \uae30\uc220\uc774\uba70, \uc544\uc9c1 \ube44\ud45c\uc900 \uae30\uc220\uc774\uc9c0\ub9cc \uc55e\uc73c\ub85c \uc6f9 \uc811\uadfc\uc131\uc5d0 \ub300\ud574 \ub9ce\uc740 \ubc1c\uc804\uc774 \uace0\ubbfc\ub420 \uac83 \uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. <a href=\\"https://developer.mozilla.org/ko/docs/Web/Accessibility/ARIA/Attributes/aria-label\\">Aria-label</a>\uc774\ub098 role\uacfc \uac19\uc740 \uccb4\uacc4\uac00 <a href=\\"https://web.dev/articles/aria-labels-and-relationships?hl=ko\\">\uc5b4\ub5bb\uac8c</a>\xa0\uc2e4\uc81c\uc801\uc778 \uc6f9 \uc811\uadfc\uc131\uc5d0 \uae30\uc5ec\ud558\ub294\uc9c0 \uc54c\uba74 \uc88b\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"f54ee99d-a6f7-4c46-a206-7e843374f2f6\\" id=\\"f54ee99d-a6f7-4c46-a206-7e843374f2f6\\">JIT\uc774 \ub354 \ube60\ub974\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4.</h2><a href=\\"https://v8.dev/blog/maglev\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://v8.dev/blog/maglev</a><p data-notion-block-id=\\"0bc786ba-0118-450d-9c79-141c6ff443ea\\"><b>\uc2ec\uc724\uc12d</b>: V8\uc758 JIT \uc778\ud130\ud504\ub9ac\ud130 \ub2e8\uacc4\uc5d0 \ud55c \ub2e8\uacc4\uac00 \ub354 \ucd94\uac00\ub418\uc5c8\uc2b5\ub2c8\ub2e4. SpiderMonkey\uc640 V8 \ub458 \ub2e4 4\ub2e8\uacc4\uc758 \uc778\ud130\ud504\ub9ac\ud130 \ub2e8\uacc4\ub97c \uac00\uc84c\ub2e4\uace0 \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4(<a href=\\"https://firefox-source-docs.mozilla.org/js/index.html#javascript-interpreter\\">SpiderMonkey</a>). \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\uc5d0\uac8c \uc774 \uae00\uc774 \ub3c4\uc6c0\uc774 \ub418\ub0d0\uace0 \ubb3c\uc5b4\ubcf4\uba74 \uc88b\uc9c0 \uc54a\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc704 \uae00\uc744 \ubcf4\uae30\ubcf4\ub2e4\ub294 \uc774 <b>\ub450 \uae00(</b><a href=\\"https://mathiasbynens.be/notes/shapes-ics\\"><b>1</b></a><b>, </b><a href=\\"https://shlrur.github.io/javascripts/javascript-engine-fundamentals-shapes-and-Inline-caches/\\"><b>1\uc758 \ud55c\uad6d\uc5b4</b></a><b>, </b><a href=\\"https://mathiasbynens.be/notes/prototypes\\"><b>2</b></a><b>, </b><a href=\\"https://shlrur.github.io/javascripts/javascript-engine-fundamentals-optimizing-prototypes/\\"><b>2\uc758 \ud55c\uad6d\uc5b4</b></a><b>)</b>\ub97c \uac15\uc870\ud558\uae30 \uc704\ud574 \uc815\ubcf4\uc131 \uae00\ub85c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"bc4aedd5-c7d6-4882-ad26-08fe56e536b0\\" id=\\"bc4aedd5-c7d6-4882-ad26-08fe56e536b0\\">Promise\ub294 monad\uac00 \uc544\ub2c8\ub2e4.</h2><a href=\\"https://rybicki.io/blog/2023/12/23/promises-arent-monads.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://rybicki.io/blog/2023/12/23/promises-arent-monads.html</a><p data-notion-block-id=\\"bbbfa10b-0b92-473a-91af-9cd019cb4c69\\"><b>\uc2ec\uc724\uc12d</b>: \ud568\uc218\ud615 \ud504\ub85c\uadf8\ub798\ubc0d\uc758 \uc815\uc218\ub77c\uace0 \uc77c\uceec\uc5b4\uc9c0\ub294 monad\uc5d0 \ub300\ud55c \uc124\uba85\uc774 \uc798 \ub418\uc5b4\uc788\uc2b5\ub2c8\ub2e4.  \uc27d\uac8c \uc124\uba85\ud558\uace0 \uc788\uc73c\ubbc0\ub85c \ud55c \ubc88 \ubcf4\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4. \ubaa8\ub098\ub4dc\uac00 \ubb34\uc5c7\uc778\uc9c0 \uad81\uae08\ud55c \uc0ac\ub78c\uc774 \ud765\ubbf8\ub86d\uac8c \ubcfc \ub9cc\ud55c \uc8fc\uc81c\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"3399142f-1019-42c9-854b-f5f92a747770\\"><b>\ucd5c\uc6d0\ube48</b>: <a href=\\"https://velog.io/@jsonkim/concrete-monad\\">\ubca8\ub85c\uadf8</a>\uc5d0\ub3c4 \ucd08\uae30 \uac1c\ub150\uc744 \uc774\ud574\ud558\uae30 \uc27d\uac8c \uc791\uc131\ud574 \ub454 \uae00\uc774 \uc788\uc5b4 \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \uba85\uc2dc\uc801 \ud0c0\uc785\uc744 \ubc18\ud658\ud558\ub294 \ud568\uc218\ub4e4\ub85c \ud558\uc5ec\uae08 \uccb4\uc774\ub2dd\ud560 \uc218 \uc788\uac8c \ud55c\ub2e4\ub294 \uac1c\ub150\uc744 \uc54c\uc544\ub450\uba74 \uc88b\uaca0\ub124\uc694. </p><h2 data-notion-block-id=\\"aef423ee-c881-4803-a5c7-d940c6246140\\" id=\\"aef423ee-c881-4803-a5c7-d940c6246140\\">React\uc5d0\uc11c \uc0c1\ud0dc \ubd88\uc77c\uce58</h2><a href=\\"https://interbolt.org/blog/react-ui-tearing/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://interbolt.org/blog/react-ui-tearing/</a><p data-notion-block-id=\\"3f9daa79-2978-4666-847c-49662370189d\\"><b>\uc2ec\uc724\uc12d</b>: React\uac00 \ub3d9\uc2dc \ubaa8\ub4dc\ub85c \ub4e4\uc5b4\uc624\uba74\uc11c <code>useState</code>\uc640 <code>useEffect</code>\uae30\ubc18\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c4 \uc678\ubd80 \uc0c1\ud0dc \ud6c5\uc5d0\uc11c <code>startTransition</code>\uc744 \uc0ac\uc6a9\ud558\uba74 \ub80c\ub354\ub9c1 \uc911\uc5d0 \uc0c1\ud0dc \ubd88\uc77c\uce58\uac00 \ubc1c\uc0dd\ub418\uc5c8\uace0, \uc774\ub97c \uc5b4\ub5bb\uac8c \ud574\uacb0\ud558\uc600\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. <code>useState</code>\uc640 <code>useEffect</code>, <code>useSyncExternalStore</code>\uc640 <code>useContext</code>\uc758 \uc7a5\ub2e8\uc810\uc740 \uc8fc\ub85c \ub77c\uc774\ube0c\ub7ec\ub9ac \uac1c\ubc1c\uc790\uac00 \uc0ac\uc6a9\ud558\uc9c0\ub9cc, \uc54c\uc544\ub450\uba74 React\uc758 \uc0c1\ud0dc\ub97c \ub2e4\ub8e8\ub294\ub370\uc5d0 \uc88b\uc73c\ubbc0\ub85c \ubcf4\uae38 \uad8c\uc7a5\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"6e1950cf-ceb7-418a-a85a-e4b7aef10d94\\" id=\\"6e1950cf-ceb7-418a-a85a-e4b7aef10d94\\">React 18\uc5d0\uc11c\uc758 \ubd88\ub9cc</h2><a href=\\"https://www.mayank.co/blog/react-server-components/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.mayank.co/blog/react-server-components/</a><p data-notion-block-id=\\"471323d7-616b-4078-b912-1d6dea8639fc\\"><b>\uc2ec\uc724\uc12d</b>: React\uc5d0\uc11c \uc18c\uac1c\ud55c Server Component\ub294 \uc0c8\ub85c\uc6b4 \ud328\ub7ec\ub2e4\uc784\uc744 \uac00\uc838\uc62c \uc904 \uc54c\uc558\uc9c0\ub9cc \uc624\ub958\ub294 \uc0c1\ub2f9\ud558\uace0 \uae30\uc874 \ub2e4\ub978 \uae30\ub2a5\ub4e4\uc758 \ub808\uac70\uc2dc\ub294 \ud574\uacb0\ub418\uc9c0 \uc54a\uc740 \ucc44 \uc0ac\uc6a9\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uae00\uc4f4\uc774\ub294 \uc774\ub97c \ubc14\ud0d5\uc73c\ub85c React\uc640 Next.js\uac00 \uac08 \uae38\uc774 \uba40\uc5c8\uc73c\uba70, \uc2dc\uc911\uc5d0\ub294 \ub808\uac70\uc2dc\ub97c \uce58\uc6b4 \ud504\ub808\uc784\uc6cc\ud06c\uac00 \ub9ce\ub2e4\ub294 \uac83\uc744 \uc778\uc9c0\ud574\ub2ec\ub77c\ub294 \ucde8\uc9c0\ub85c \uae00\uc744 \uc37c\ub2e4\uace0 \ud569\ub2c8\ub2e4(<a href=\\"https://pilcrow.vercel.app/blog/nextjs-why\\">\ube44\uc2b7\ud55c \uae00</a>). \uac1c\uc778\uc801\uc73c\ub85c\ub294 React\uc758 \ub113\uc740 \uc0dd\ud0dc\uacc4(\ud2b9\ud788 UI\uc5d0 \uacb0\ud569\ub41c)\ub97c \ub300\uccb4\ud558\uc9c0\ub294 \ubabb\ud558\uc9c0\ub9cc \ub113\uc740 \uc0dd\ud0dc\uacc4\ub97c \ub9ce\uc774 \ud65c\uc6a9\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c\uba74 \ub2e4\ub978 \ud504\ub808\uc784\uc6cc\ud06c\uc5d0 \ub208\ub3c5\uc744 \ub4e4\uc5ec\ub3c4 \uad1c\ucc2e\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"c1f44364-8a9f-4405-be18-0c4eb9a5cf53\\" id=\\"c1f44364-8a9f-4405-be18-0c4eb9a5cf53\\">React\uc758 flushsync\ub294 \ubb34\uc5c7\uc778\uac00\uc694?</h2><a href=\\"https://julesblom.com/writing/flushsync\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://julesblom.com/writing/flushsync</a><p data-notion-block-id=\\"881040f0-b958-4fd1-b5d8-2fdb26f90661\\"><b>\uc2ec\uc724\uc12d</b>: flushsync\ub294 \ube44\ub3d9\uae30\uc801\uc73c\ub85c \uc5c5\ub370\uc774\ud2b8\ud558\ub294 <code>set&#x3C;state></code>\ub97c \uc989\uc2dc \uc5c5\ub370\uc774\ud2b8\ud558\ub3c4\ub85d \uac15\uc81c\ud558\ub294 \ud568\uc218\uc785\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 flushsync\uac00 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0 \uc2dc\uac01\uc801\uc73c\ub85c \ubcf4\uc5ec\uc8fc\uace0, \uc5b4\ub514\uc5d0 \uc4f0\uc774\ub294\uc9c0 \uc54c\ub824\uc90d\ub2c8\ub2e4. \uae00\uc5d0\uc11c \ubcf4\uc5ec\uc900\ub300\ub85c form\uc5d0\uc11c \ub9ce\uc774 \uc0ac\uc6a9\ub420 \uac83\uc73c\ub85c \ubcf4\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc5b8\uc81c\ub098 \uc545\uc6a9\uc740 \uc88b\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc7a0\uae50 \ub098\uc624\ub294 \uac1c\ub150\uc778 <code>render</code> - <code>commit</code>\uac1c\ub150\uc744 \uc54c\uace0\uc2f6\ub2e4\uba74 <a href=\\"https://blog.isquaredsoftware.com/2020/05/blogged-answers-a-mostly-complete-guide-to-react-rendering-behavior/\\">\uc774 \uae00</a>\uc744 \ucc38\uace0\ud574\uc8fc\uc138\uc694.</p><h2 data-notion-block-id=\\"9cd160ef-1285-44a9-b4e0-32f14f6a8e4e\\" id=\\"9cd160ef-1285-44a9-b4e0-32f14f6a8e4e\\">React\uc758 form hook \uc0dd\uc131</h2><a href=\\"https://blog.logrocket.com/understanding-react-useformstate-useformstatus-hooks/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.logrocket.com/understanding-react-useformstate-useformstatus-hooks/</a><p data-notion-block-id=\\"f1885584-004f-46e8-b3c6-137b4c495c96\\"><b>\uc2ec\uc724\uc12d</b>: \uc2e4\ud5d8 \uae30\ub2a5\uc778 <code>useFormState</code>\uc640 <code>useFormStatus</code>\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc774\ub7f0 \uae30\ub2a5\ub3c4 \uc788\ub2e4\ub77c\ub294 \uac83\ub9cc \uc54c\uc544\ub450\uace0 \uc2e4\uc81c \uae30\ub2a5\uc744 \uc0ac\uc6a9\ud560 \uac83\uc774\ub77c\uba74 <code>react-hook-form</code>\uc744 \uc0ac\uc6a9\ud558\uc138\uc694 \ud83d\ude42</p><h2 data-notion-block-id=\\"bb13d8e5-80b2-4116-b52f-e778873a8a4c\\" id=\\"bb13d8e5-80b2-4116-b52f-e778873a8a4c\\">Next.js\uc758 \uc2e0\uae30\ub2a5</h2><a href=\\"https://www.builder.io/blog/nextjs-14-intercepting-routes\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.builder.io/blog/nextjs-14-intercepting-routes</a><a href=\\"https://www.builder.io/blog/nextjs-14-parallel-routes\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.builder.io/blog/nextjs-14-parallel-routes</a><p data-notion-block-id=\\"bbdd4eb9-1092-4dcf-b6ae-3475060b0f2e\\"><b>\uc2ec\uc724\uc12d</b>: Next.js\uc758 \uc2e0\uae30\ub2a5\uc740 \ud56d\uc0c1 \uc0c8\ub86d\uc2b5\ub2c8\ub2e4. \uc800\ub294 \ub458 \uc911\uc5d0 intercepting routes\uc5d0 \ub354 \uad00\uc2ec\uc774 \uac11\ub2c8\ub2e4. \ub9e4\ub044\ub7ec\uc6b4 UX\uc640 \ud568\uaed8 \uc6f9\uc744 \uc0ac\uc6a9\ud558\uac8c \ud558\ub824\uba74 Modal\uc744 \uc5f4\uc5c8\uc744 \ub54c URL \ubcc0\uacbd\uc774 \ud544\uc694\ud55c \uacbd\uc6b0\uac00 \uc788\ub294\ub370(ex. \uc778\uc2a4\ud0c0\uadf8\ub7a8\uc758 \uac8c\uc2dc\ubb3c) \uc774\ub97c \uad6c\ud604\ud558\uae30 \uc704\ud574 \ub9ce\uc740 \ub178\ub825\uc774 \ud544\uc694\ud55c\ub370, \uc774\ub97c \uae30\ub2a5\uc73c\ub85c \ucd9c\uc2dc\ud588\ub2e4\ub294 \uac83\uc774 \uc88b\uc740 \ubd80\ubd84\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><p data-notion-block-id=\\"f8ad8b9f-dc4b-4c5f-a75e-93a7dc5ac8df\\"><b>\uae40\ub300\uad00</b>: NextJS\ub97c \ud65c\uc6a9\ud558\uba74\uc11c page\ub77c\ub294 \ubd84\ud560 \ubc29\uc2dd\uc744 \ub2e4\uc591\ud558\uac8c \ud560 \uc218 \uc788\ub294 \uae30\ub2a5\ub4e4\uc744 \uc18c\uac1c\ud558\ub294 \ub0b4\uc6a9\uc785\ub2c8\ub2e4. \uc800\ub294 Parallel Route \uae30\uc220\uc5d0 \ub354 \ud765\ubbf8\uac00 \uac11\ub2c8\ub2e4. \uc81c\uac00 \ubcf4\uc558\uc744 \ub54c\uc5d0\ub294 Parallel Route\ub294 page\ub97c \ucef4\ud3ec\ub10c\ud2b8\ucc98\ub7fc \ucc98\ub9ac\ud560 \uc218 \uc788\ub294 \ubc29\uc2dd\uc774\ub77c\uace0 \uc0dd\uac01\ub429\ub2c8\ub2e4.\uc5b4\ub5a4 \uac1c\ubc1c \uc0c1\ud669\uc5d0 \ub530\ub77c\uc11c, \uc131\ub2a5\uc801\uc73c\ub85c \ub2e8\uc21c \ucef4\ud3ec\ub10c\ud2b8\uac00 \uc88b\uc744\uc9c0? page\uc5d0\uc11c parallel Route\ub97c \ud1b5\ud574 \ud558\uba74 \uc88b\uc744\uc9c0\ufeff? \ub2e4\uc591\ud55c \uc0c1\ud669\uc5d0\uc11c\uc758 \uc131\ub2a5 \ube44\uad50\ub97c \ud1b5\ud574 \uc55e\uc73c\ub85c NextJS\uc5d0\uc11c\uc758 \uae30\ub2a5\uc744 \ucd5c\uc801\ud654\ud560 \uc218 \uc788\uc744\uc9c0\uac00 \uae30\ub300\uac00 \ub429\ub2c8\ub2e4</p><h2 data-notion-block-id=\\"d41a6628-03f4-40a7-b9da-635593c720d5\\" id=\\"d41a6628-03f4-40a7-b9da-635593c720d5\\">\ub3d9\ud615 \ub9e4\ud551 \ud0c0\uc785\uc774 \ubb34\uc5c7\uc778\uac00\uc694?</h2><a href=\\"https://andreasimonecosta.dev/posts/what-the-heck-is-a-homomorphic-mapped-type/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://andreasimonecosta.dev/posts/what-the-heck-is-a-homomorphic-mapped-type/</a><p data-notion-block-id=\\"34ce552d-b497-4c0a-bef9-ef08386d6355\\"><b>\uc2ec\uc724\uc12d</b>: TypeScript\uc758 \uace0\uae09 \uae30\ub2a5\uc744 \uc0ac\uc6a9\ud558\ub824\uba74 \uc774\ud574\ud574\uc57c \ud560 \uac1c\ub150 \uc911 \ud558\ub098\ub97c \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ud574\ud558\uae30 \ud798\ub4e4\ub354\ub77c\ub3c4 \uc720\ud2f8\ub9ac\ud2f0 \ud0c0\uc785\uc774 \uc81c\ub108\ub9ad \uc548\uc5d0 \ub4e4\uc5b4\uac00\ub294 \ud0c0\uc785\uc5d0 \ub530\ub77c \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0\ub9cc \uc54c\uace0 \uc788\uc73c\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"b810d94c-19eb-4a95-9d17-7917423f7211\\" id=\\"b810d94c-19eb-4a95-9d17-7917423f7211\\">\ud1a0\uc2a4\uc758 \ub85c\uae45 \uac1c\ubc1c \uc77c\uc9c0</h2><a href=\\"https://toss.tech/article/engineering-note-5\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://toss.tech/article/engineering-note-5</a><p data-notion-block-id=\\"4a70ba7b-e04e-4629-96af-74721472ecce\\"><b>\uc2ec\uc724\uc12d</b>: \uc774 \uae00\uc744 \uac00\uc838\uc628 \uc774\uc720\ub294 \\"\ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc0ac\uc6a9\ud558\ub294 \uac1c\ubc1c\uc790\ub294 \uc5b4\ub514\uae4c\uc9c0 \uc54c\uace0\uc788\uc5b4\uc57c \ud558\ub294\uac00\\"\uc5d0 \ub300\ud55c \uace0\ubbfc\uc774 \uc798 \ub179\uc544\ub4e4\uc5b4 \uc788\uc5b4\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc774 \uc815\ub2f5\uc774\ub77c\ub294 \uac83\uc774 \uc544\ub2c8\uace0, \ud56d\uc0c1 \uacb0\uc815(\uc5ec\uae30\uc11c\ub294 \uc554\uc2dc\uc801\uc73c\ub85c \uc2e4\ud589\ud558\ub294 \uac83\uacfc \uba85\uc2dc\uc801\uc73c\ub85c \uc2e4\ud589\ud558\ub294 \uac83)\uc5d0 \ub300\ud55c \uc7a5\ub2e8\uc810\uc744 \uace0\ub824\ud558\uba74\uc11c \uacb0\uc815\ud574\uc57c \ud55c\ub2e4\ub294 \uac83\uc744 \uc54c\uba74 \uc88b\uaca0\ub2e4\ub294 \ucde8\uc9c0\uc5d0\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \ubb3c\ub860 \ubb34\uc5c7\uc774\ub4e0 \ubb38\uc11c\ud654\ub97c \uc798 \ud574\ub193\uc73c\uba74 \uc0c1\uc1c4\ub418\uaca0\uc9c0\ub9cc\uc694.</p><p data-notion-block-id=\\"aeef6cf3-29f0-439c-a3c3-61c4ee80fa95\\"><b>\uae40\ub300\uad00</b>: \uc800\ub294 \uae00\uc758 \ub0b4\uc6a9\uc5d0\uc11c \uc800\uc758 \ubb38\uc81c\uc810\uc744 \ucc3e\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4.  \uc6f9\ud398\uc774\uc9c0 \ub85c\uae45 \uad00\ub828\ud55c \uac1c\ubc1c\ud558\uba74\uc11c \ub85c\uae45 \ucf54\ub4dc\ub4e4\ub9cc \ub530\ub85c \ubd84\ub9ac\ud574\uc11c \uad00\ub9ac\ud55c\ub2e4\ub294 \ub9c9\uc5f0\ud55c \uc0dd\uac01\uc73c\ub85c \ud588\uc5c8\ub294\ub370, \ud1a0\uc2a4\uc5d0\uc11c\ub294 \uc5b4\ub5bb\uac8c \uad00\uc2ec\uc0ac\ub97c \ubd84\ub9ac\ud558\uc5ec \ucc98\ub9ac\ud558\ub294 \uac83\uc5d0 \uc9d1\uc911\ud558\ub294 \uac00\uc5d0 \ub300\ud574 \uc54c\uac8c\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uc81c\uac00 \ub85c\uae45\ud558\ub294 \uc11c\ube44\uc2a4\ub97c \uad00\ub9ac\ud558\ub294 \ud1a0\uc2a4\uc5d0 \ube44\ud574\uc11c \ub85c\uae45\ud558\ub294 \uc591\uc774 \ub9ce\uc9c0 \uc54a\uc544 \ub2e8\uc21c \ucf54\ub4dc \ubd84\ub9ac\ub97c \ud574\ub3c4 \ud070 \ubb34\ub9ac\uac00 \uc5c6\uc9c0\ub9cc, \uc55e\uc73c\ub85c\uc758 \ud655\uc7a5\uc131\uacfc \uad00\ub828\ud558\uc5ec \ub85c\uae45\uc5d0 \ub300\ud55c \uad00\uc2ec\uc0ac \ubd84\ub9ac\ub97c \uc5b4\ub5bb\uac8c \ud560\uc9c0 \ud55c\ubc88 \ub354 \uc0dd\uac01\ud574\ubcfc \ud544\uc694\uac00 \uc788\uaca0\uc2b5\ub2c8\ub2e4. </p><h2 data-notion-block-id=\\"2e1d5a32-778b-4d55-b1a0-a8e413019419\\" id=\\"2e1d5a32-778b-4d55-b1a0-a8e413019419\\">TypeScript \uc624\ub958 \ud574\uacb0 \ud29c\ud1a0\ub9ac\uc5bc</h2><a href=\\"https://www.totaltypescript.com/tutorials/solving-typescript-errors\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.totaltypescript.com/tutorials/solving-typescript-errors</a><p data-notion-block-id=\\"3be89c7d-7147-4f6e-909a-fc0d38874726\\">\uae30\uc0ac\ub294 \uc544\ub2c8\uace0 \ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8 \uc785\ubb38\uc5d0 \ub3c4\uc6c0\uc774 \ub420\ub9cc\ud55c \ud29c\ud1a0\ub9ac\uc5bc\uc774\ub77c\uace0 \uc0dd\uac01\ud574\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \uc624\ub958\ub97c <code>any</code>\ub098 <code>@ts-ignore</code>\ub85c \ubb34\uc2dc\ud558\ub294 \uac83\uc740 \ubcf4\ud1b5 \uc88b\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. </p>"}')}}]);